shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const path = 'src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts';
let content = fs.readFileSync(path, 'utf8');

// Fix PromptBuilder
content = content.replace(
  /const promptBuilder = new PromptBuilder\(\{[\s\S]*?\}\);/,
  "const promptBuilder = new PromptBuilder({identity: 'You are HAL.'});"
);

// Fix max-expects
content = content.replace(
  /await expect\(orchestrator.processMessage\(createSession\('hello'\)\)\)\.rejects\.toThrow\([\s\S]*?'Database connection failed in beforeSession'[\s\S]*?\);[\s\S]*?expect\(caughtError\)\.toBe\(errorToThrow\);[\s\S]*?expect\(afterSessionRan\)\.toBe\(true\);/,
  `let rejectedMsg: string | undefined;
    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      rejectedMsg = (e as Error).message;
    }

    expect({
      rejectedMsg,
      caughtError,
      afterSessionRan,
    }).toEqual({
      rejectedMsg: 'Database connection failed in beforeSession',
      caughtError: errorToThrow,
      afterSessionRan: true,
    });`
);

fs.writeFileSync(path, content);
EOF
node patch.js

